import functools
import inspect
from typing import ForwardRef, Any, Callable, Dict

# Mock evaluate_forwardref as pydantic does
def evaluate_forwardref(annotation, globalns, localns):
    if isinstance(annotation, ForwardRef):
        return eval(annotation.__forward_code__, globalns, localns)
    return annotation

def get_typed_annotation(annotation, globalns):
    if isinstance(annotation, str):
        annotation = ForwardRef(annotation)
        annotation = evaluate_forwardref(annotation, globalns, globalns)
    return annotation

def get_typed_signature_old(call):
    signature = inspect.signature(call)
    globalns = getattr(call, "__globals__", {})
    typed_params = [
        inspect.Parameter(
            name=param.name,
            kind=param.kind,
            default=param.default,
            annotation=get_typed_annotation(param.annotation, globalns),
        )
        for param in signature.parameters.values()
    ]
    return inspect.Signature(typed_params)

def get_typed_signature_new(call):
    while hasattr(call, "__wrapped__"):
        call = call.__wrapped__
    signature = inspect.signature(call)
    globalns = getattr(call, "__globals__", {})
    typed_params = [
        inspect.Parameter(
            name=param.name,
            kind=param.kind,
            default=param.default,
            annotation=get_typed_annotation(param.annotation, globalns),
        )
        for param in signature.parameters.values()
    ]
    return inspect.Signature(typed_params)

# Setup modules
with open('mod_original.py', 'w') as f:
    f.write('def original(a: "SomeType"):\n    return a\n\nclass SomeType:\n    pass')

with open('mod_wrapper.py', 'w') as f:
    f.write('import functools\nfrom mod_original import original\n\ndef wrapper(func):\n    @functools.wraps(func)\n    def wrapped(*args, **kwargs):\n        return func(*args, **kwargs)\n    return wrapped\n\nwrapped_func = wrapper(original)')

import mod_wrapper

